mapper.select:
SELECT
  (SELECT COALESCE(SUM(a.balance),0) FROM scx_adx_advertiser a
   WHERE a.deleted=0
   AND a.id = #{advertiserId}
  ) AS totalBalance,
  COALESCE(SUM(CASE WHEN b.mode='RECHARGE' AND b.status='POSTED' THEN b.amount ELSE 0 END),0) AS rechargeAmount,
  COALESCE(SUM(CASE WHEN b.mode='CPC' AND b.status='POSTED' THEN b.amount ELSE 0 END),0) AS cpcSpend,
  COALESCE(SUM(CASE WHEN b.mode='CPA' AND b.status='POSTED' THEN b.amount ELSE 0 END),0) AS cpaSpend,
  SUM(b.mode='CPC' AND b.status='REJECTED') AS rejectedCharges,
  SUM(b.mode='CPA' AND b.status='REJECTED') AS cpaRejectedCharges
FROM scx_ocpx_billing_entry b
WHERE b.create_time >= #{start} AND b.create_time < #{end}
AND b.debug_execution_id IS NULL
AND b.advertiser_id = #{advertiserId}
AND (b.mode='RECHARGE' OR (b.mode='CPA' AND b.status='REJECTED'
  AND b.channel_id = #{channelId}
  AND b.app_link_id = #{appLinkId}
  AND b.monitor_id = #{monitorId}
) OR EXISTS (
  SELECT 1 FROM scx_ocpx_event e WHERE e.event_id=b.charge_event_id AND e.is_debug=0
  AND e.channel_id = #{channelId}
  AND e.app_link_id = #{appLinkId}
  AND e.monitor_id = #{monitorId}
))
